CREATE TABLE "followers" ("followerId" integer NOT NULL, "followedId" integer NOT NULL, PRIMARY KEY ("followerId", "followedId"));
CREATE TABLE "tags-to-super-tags" ("tagId" integer NOT NULL, "superTagId" integer NOT NULL, CONSTRAINT "UQ_73e578b4f57850c258a3a2e398a" UNIQUE ("tagId", "superTagId"), CONSTRAINT "FK_78485c5b85b89e77f0072ddfabe" FOREIGN KEY ("superTagId") REFERENCES "super-tags" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "FK_98532bb607346dfdde485852469" FOREIGN KEY ("tagId") REFERENCES "tags" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, PRIMARY KEY ("tagId", "superTagId"));
CREATE TABLE "items-to-tags" ("itemId" integer NOT NULL, "tagId" integer NOT NULL, CONSTRAINT "UQ_08e8fcc7f2858c083c06d88a497" UNIQUE ("itemId", "tagId"), CONSTRAINT "FK_9d06a71bf292bd744f1f7bf3218" FOREIGN KEY ("itemId") REFERENCES "items" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "FK_af9d7dec79b6af6dfbee5dcbde8" FOREIGN KEY ("tagId") REFERENCES "tags" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, PRIMARY KEY ("itemId", "tagId"));
CREATE TABLE "items-to-accounts" ("itemId" integer NOT NULL, "accountId" integer NOT NULL, "wishlist" boolean NOT NULL DEFAULT (0), CONSTRAINT "FK_795cd497f53706b0f9267ccfe17" FOREIGN KEY ("itemId") REFERENCES "items" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "FK_684fc77dc5328669f73f9c53dfa" FOREIGN KEY ("accountId") REFERENCES "accounts" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, PRIMARY KEY ("itemId", "accountId"));
CREATE TABLE "super-tags" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar(64) NOT NULL, CONSTRAINT "UQ_07c965393382b8f6b46464eae7e" UNIQUE ("name"));
CREATE TABLE "tags" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar(64) NOT NULL, CONSTRAINT "UQ_d90243459a697eadb8ad56e9092" UNIQUE ("name"));
CREATE TABLE "items" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "url" varchar(512) NOT NULL, "albumId" integer, "releaseDate" date, "lastProcessingDate" date, "isBusy" boolean NOT NULL DEFAULT (0), "failedCount" integer NOT NULL DEFAULT (0), imageUrl varchar(512), CONSTRAINT "UQ_296d62dba3927bafd8fd0aefc22" UNIQUE ("url"), CONSTRAINT "FK_829d66d4947b53d10d511e80f4f" FOREIGN KEY ("albumId") REFERENCES "items" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE TABLE "accounts" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "url" varchar(512) NOT NULL, "lastProcessingDate" date, "isBusy" boolean NOT NULL DEFAULT (0), "failedCount" integer NOT NULL DEFAULT (0), CONSTRAINT "UQ_552c1c20aa3547ce59bec7abba4" UNIQUE ("url"));
CREATE INDEX "IDX_829d66d4947b53d10d511e80f4" ON "items" ("albumId") ;
